(2051527, 282159, 49865, '<td valign="top">Deliciously amusing title.</td>', 'Deliciously amusing title.', '2006-01-18 00:16:39.000000', NULL, 1),
(2051536, 282662, 49865, '<td valign="top">Very clever.</td>', 'Very clever.', '2006-01-18 00:17:48.000000', NULL, 1),
(2051549, 281301, 49865, '<td valign="top">I presume the grave marker on the far left reads "Rode", but it''s a bit hard to tell here.  A different angle would''ve been better, maybe if you had taken the photo from the other side of the road further back and turned to face the cemetary slightly. Still nice though.</td>', 'I presume the grave marker on the far left reads "Rode", but it''s a bit hard to tell here.  A different angle would''ve been better, maybe if you had taken the photo from the other side of the road further back and turned to face the cemetary slightly. Still nice though.', '2006-01-18 00:19:00.000000', NULL, 1),
(2051589, 282449, 49865, '<td valign="top">I had such an enormous urge to do a photo like this and drove around at 1 am one morning looking for roads that promised ideal moonsets. Didn''t find anything that worked in my neck of the heavily-wooded state of CT, but here''s proof that the concept works. Nice execution.</td>', 'I had such an enormous urge to do a photo like this and drove around at 1 am one morning looking for roads that promised ideal moonsets. Didn''t find anything that worked in my neck of the heavily-wooded state of CT, but here''s proof that the concept works. Nice execution.', '2006-01-18 00:24:59.000000', NULL, 1),
(2051598, 282159, 29269, '<td valign="top">Great DOF choice. Perfect theme for the challenge. The overall yellow tone bothers me a bit - not sure that it is the best choice for the photo.<br/>I''m sure I''ll be back to bump this one later.</td>', 'Great DOF choice. Perfect theme for the challenge. The overall yellow tone bothers me a bit - not sure that it is the best choice for the photo.I''m sure I''ll be back to bump this one later.', '2006-01-18 00:26:35.000000', NULL, 1),
