(2054641, 282970, 32854, '<td valign="top">I like the angle. I think it would look nicer if you used a smaller aperture to get everything, or at least the background, into focus.</td>', 'I like the angle. I think it would look nicer if you used a smaller aperture to get everything, or at least the background, into focus.', '2006-01-18 14:59:45.000000', NULL, 1),
(2054648, 282768, 32854, '<td valign="top">Nice composition and location. However, the whole pic is on the blurry side, and parts of the trees are overexposed at the top.</td>', 'Nice composition and location. However, the whole pic is on the blurry side, and parts of the trees are overexposed at the top.', '2006-01-18 15:00:49.000000', NULL, 1),
(2054659, 280471, 32854, '<td valign="top">Intriguing subject matter, but this really feels like more of a snapshot. I guess it must have been a quick opportunity to photograph, I guess.</td>', 'Intriguing subject matter, but this really feels like more of a snapshot. I guess it must have been a quick opportunity to photograph, I guess.', '2006-01-18 15:03:10.000000', NULL, 1),
