(2055525, 282868, 26464, '<td valign="top">i want to drive there right now! nice</td>', 'i want to drive there right now! nice', '2006-01-18 18:28:41.000000', NULL, 1),
(2055530, 282877, 49489, '<td valign="top">i think this would score higher if it were more of the road</td>', 'i think this would score higher if it were more of the road', '2006-01-18 18:29:17.000000', NULL, 1),
(2055548, 282967, 26464, '<td valign="top">unique mirror shot</td>', 'unique mirror shot', '2006-01-18 18:32:10.000000', NULL, 1),
(2055550, 280471, 16488, '<td valign="top">I am so compelled to look at this image and try to understand the story of this man. One athletic leg, one mangled like a polio victim. The easy stride of the goats contrasts with the odd posture of the man. I am so in his world and yet don''t feel as if I''m a voyeur at a freak show. The incidental people add interest, too. The couple in front of the furniture store sign, unaware. The gaze of the youth from the upper right, catching the photographer at work. 5 worlds at least--modern wealth (the couple), daily business (people upper left), the youth interested and outside of the situation, the goatherd with his goats, and the photographer. Interesting confluence!</td>', 'I am so compelled to look at this image and try to understand the story of this man. One athletic leg, one mangled like a polio victim. The easy stride of the goats contrasts with the odd posture of the man. I am so in his world and yet don''t feel as if I''m a voyeur at a freak show. The incidental people add interest, too. The couple in front of the furniture store sign, unaware. The gaze of the youth from the upper right, catching the photographer at work. 5 worlds at least--modern wealth (the couple), daily business (people upper left), the youth interested and outside of the situation, the goatherd with his goats, and the photographer. Interesting confluence!', '2006-01-18 18:32:36.000000', NULL, 1),
(2055636, 282736, 49773, '<td valign="top">i think that you unnecessarily envolved sky in your photo, it would''ve been better if you turned your camera horizontaly, otherwise good photo</td>', 'i think that you unnecessarily envolved sky in your photo, it would''ve been better if you turned your camera horizontaly, otherwise good photo', '2006-01-18 18:52:21.000000', NULL, 1),
