(2060570, 282555, 44490, '<td valign="top">Nice idea, color, composition, and feeling.  Brush in left foreground is too close, too much, and too distracting, cropping some of it out would be better.</td>', 'Nice idea, color, composition, and feeling.  Brush in left foreground is too close, too much, and too distracting, cropping some of it out would be better.', '2006-01-19 17:59:20.000000', NULL, 1),
(2060572, 282932, 43774, '<td valign="top">I have no idea why you chose to flip your photo. I don''t think it adds anything</td>', 'I have no idea why you chose to flip your photo. I don''t think it adds anything', '2006-01-19 17:59:36.000000', NULL, 1),
(2060575, 282342, 32132, '<td valign="top">good study, nice photo.</td>', 'good study, nice photo.', '2006-01-19 18:01:02.000000', NULL, 1),
