INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2066860, 282932, 5354, '<td valign="top">Hello Australia ;-)<br/>Not sure the rotation really saves what is in essence a fairly uninspired image.</td>', 'Hello Australia ;-)Not sure the rotation really saves what is in essence a fairly uninspired image.', '2006-01-21 05:42:04.000000', NULL, 1),
(2066862, 279728, 24169, '<td valign="top">Seems a bit slanted to me? Or maybe it is the leading lines - very hard for me to tell!</td>', 'Seems a bit slanted to me? Or maybe it is the leading lines - very hard for me to tell!', '2006-01-21 05:43:20.000000', NULL, 1),
(2066864, 282934, 5354, '<td valign="top">Flat light has tricked the camera into over exposing this. You could have had deep rich greens and browns instead itsd washed out all the colour.<br/>If you haven''t already done so go and buy a hand held light meter to double check what the camera has decided is the ''best exposure''. Use it to work out what the actual exposure should be based on the thing (mud in this case) which is the main subject and not on the overall ambient light.</td>', 'Flat light has tricked the camera into over exposing this. You could have had deep rich greens and browns instead itsd washed out all the colour.If you haven''t already done so go and buy a hand held light meter to double check what the camera has decided is the ''best exposure''. Use it to work out what the actual exposure should be based on the thing (mud in this case) which is the main subject and not on the overall ambient light.', '2006-01-21 05:45:02.000000', NULL, 1),
(2066865, 281360, 5354, '<td valign="top">Doesn''t do it for me. The eyes are too dark, I can''t see into the shadows and connect.</td>', 'Doesn''t do it for me. The eyes are too dark, I can''t see into the shadows and connect.', '2006-01-21 05:46:22.000000', NULL, 1),
(2066867, 282760, 5354, '<td valign="top">Apologies if this sounds rude, but first impressions are usually the most honest.<br/>I find it flat and boring, no specific point of interest. Probably should have been one to throw in the bin.<br/>Sorry</td>', 'Apologies if this sounds rude, but first impressions are usually the most honest.I find it flat and boring, no specific point of interest. Probably should have been one to throw in the bin.Sorry', '2006-01-21 05:48:11.000000', NULL, 1),
(2066869, 282885, 5354, '<td valign="top">NIce line, great sweeps and termination on the red house. Shame the sky didn''t cooperate and provide a little cloud or two.<br/>The top half may have benefitted from the use of a low value ND Grad filter to bring down the slightly over exposed sky and background.</td>', 'NIce line, great sweeps and termination on the red house. Shame the sky didn''t cooperate and provide a little cloud or two.The top half may have benefitted from the use of a low value ND Grad filter to bring down the slightly over exposed sky and background.', '2006-01-21 05:50:29.000000', NULL, 1),
(2066871, 281719, 5354, '<td valign="top">Certainly a different interpretation ;-)<br/>As a portrate its OK, not something I''m going to spring the wallet to buyt though.</td>', 'Certainly a different interpretation ;-)As a portrate its OK, not something I''m going to spring the wallet to buyt though.', '2006-01-21 05:51:41.000000', NULL, 1),
(2066872, 282357, 5354, '<td valign="top">You will find that toys never do well in DPC.<br/>DOF way too shallow, lighting bland, composition weak.</td>', 'You will find that toys never do well in DPC.DOF way too shallow, lighting bland, composition weak.', '2006-01-21 05:53:04.000000', NULL, 1),
