(2069418, 283008, 42638, '<td valign="top">Wonderful picture, love the grain and exposure, really feels like home for me!</td>', 'Wonderful picture, love the grain and exposure, really feels like home for me!', '2006-01-21 23:17:59.000000', NULL, 1),
(2069419, 282604, 47852, '<td valign="top">Creative!  I like the unique idea behind this one.  Love how everyone is just taking a break, and you can see the road going on ahead of them.  Well done!</td>', 'Creative!  I like the unique idea behind this one.  Love how everyone is just taking a break, and you can see the road going on ahead of them.  Well done!', '2006-01-21 23:18:22.000000', NULL, 1),
(2069421, 282449, 47852, '<td valign="top">Great angle and perfectly lined up.  Fantastic!</td>', 'Great angle and perfectly lined up.  Fantastic!', '2006-01-21 23:18:43.000000', NULL, 1),
(2069422, 281502, 42638, '<td valign="top">Wow, Very nice! Love the detail here, interesting perspective, nice interpretation.</td>', 'Wow, Very nice! Love the detail here, interesting perspective, nice interpretation.', '2006-01-21 23:19:05.000000', NULL, 1),
(2069425, 281280, 42638, '<td valign="top">Very nice, Love the color and blur you used.</td>', 'Very nice, Love the color and blur you used.', '2006-01-21 23:20:05.000000', NULL, 1),
(2069426, 282141, 47852, '<td valign="top">Beautiful shot!  Love the warm glow in this one and all the curves.  The star shaped lights are a little grainy up at the top, which seems out of place in the rest of the photo.  Very well done!</td>', 'Beautiful shot!  Love the warm glow in this one and all the curves.  The star shaped lights are a little grainy up at the top, which seems out of place in the rest of the photo.  Very well done!', '2006-01-21 23:20:22.000000', NULL, 1),
(2069429, 281808, 42638, '<td valign="top">Wow, Fantastic, Lov ethe perspective here. The towers are great and you got all of the second one, Amazing picture.</td>', 'Wow, Fantastic, Lov ethe perspective here. The towers are great and you got all of the second one, Amazing picture.', '2006-01-21 23:21:18.000000', NULL, 1),
(2069434, 281786, 47852, '<td valign="top">Needed the title on this one to really tie it into the challenge, but it''s a fantastic shot with great lines.  My only little gripe is that the snail''s antenna blends right into the edge of the leaf.  Great job!!!</td>', 'Needed the title on this one to really tie it into the challenge, but it''s a fantastic shot with great lines.  My only little gripe is that the snail''s antenna blends right into the edge of the leaf.  Great job!!!', '2006-01-21 23:22:28.000000', NULL, 1),
(2069435, 282340, 47852, '<td valign="top">Wow!  Definately a road... but what a creative idea.  One of my top picks from this challenge!</td>', 'Wow!  Definately a road... but what a creative idea.  One of my top picks from this challenge!', '2006-01-21 23:22:31.000000', NULL, 1),
(2069441, 282694, 42638, '<td valign="top">Simply amazing. The clarity is fantastic, so crisp and vibrant.</td>', 'Simply amazing. The clarity is fantastic, so crisp and vibrant.', '2006-01-21 23:24:03.000000', NULL, 1),
(2069446, 282685, 47852, '<td valign="top">Seems a bit too tightly cropped... but then I have no idea what was there that you might have needed to take out of the shot.  I like how you are led around that corner with this shot.</td>', 'Seems a bit too tightly cropped... but then I have no idea what was there that you might have needed to take out of the shot.  I like how you are led around that corner with this shot.', '2006-01-21 23:25:08.000000', NULL, 1),
(2069453, 281536, 4380, '<td valign="top">classic and i love it... 8</td>', 'classic and i love it... 8', '2006-01-21 23:26:34.000000', NULL, 1),
(2069459, 282719, 4380, '<td valign="top">perfect angle/perspective...perfectly composed.. great image</td>', 'perfect angle/perspective...perfectly composed.. great image', '2006-01-21 23:27:35.000000', NULL, 1),
(2069464, 281594, 4380, '<td valign="top">i simply like this one...great perspective.... 9</td>', 'i simply like this one...great perspective.... 9', '2006-01-21 23:28:24.000000', NULL, 1),
(2069473, 282789, 4380, '<td valign="top">the image is too small, colours and composition is perrfect for my taste, i also like the sky and light and shades... 8</td>', 'the image is too small, colours and composition is perrfect for my taste, i also like the sky and light and shades... 8', '2006-01-21 23:32:22.000000', NULL, 1),
(2069476, 280482, 4380, '<td valign="top">nice work... 7</td>', 'nice work... 7', '2006-01-21 23:33:23.000000', NULL, 1),
(2069489, 282885, 4380, '<td valign="top">greatly composed...</td>', 'greatly composed...', '2006-01-21 23:35:51.000000', NULL, 1),
(2069491, 280555, 42638, '<td valign="top">Wow, Fantastic, Love the sky and white trees here, then the coal black road. Nicely done!</td>', 'Wow, Fantastic, Love the sky and white trees here, then the coal black road. Nicely done!', '2006-01-21 23:36:21.000000', NULL, 1),
(2069517, 279905, 32854, '<td valign="top">Nice perspective.</td>', 'Nice perspective.', '2006-01-21 23:44:31.000000', NULL, 1),
(2070027, 281328, 40359, '<td valign="top">very nice, I like that the road and the churh are the two brightest object in the shot.</td>', 'very nice, I like that the road and the churh are the two brightest object in the shot.', '2006-01-22 06:56:34.000000', NULL, 1),
(2070030, 281280, 40359, '<td valign="top">I like the effect used, good job</td>', 'I like the effect used, good job', '2006-01-22 06:57:25.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2070038, 282993, 40359, '<td valign="top">Is that you holding up traffic?  Nice shot, one of the best in the challenge.</td>', 'Is that you holding up traffic?  Nice shot, one of the best in the challenge.', '2006-01-22 06:59:37.000000', NULL, 1),
(2070041, 280925, 40359, '<td valign="top">Pretty country, I like it.</td>', 'Pretty country, I like it.', '2006-01-22 07:01:28.000000', NULL, 1),
(2070043, 282985, 40359, '<td valign="top">Tough shot to get right, you did it though.</td>', 'Tough shot to get right, you did it though.', '2006-01-22 07:02:21.000000', NULL, 1),
(2070047, 280691, 40359, '<td valign="top">WOW!  I love it.</td>', 'WOW!  I love it.', '2006-01-22 07:03:15.000000', NULL, 1),
(2070099, 280471, 40359, '<td valign="top">I have spent more time admiring this shot than any other one thus far.  Sheer determination is the only way to describe it.</td>', 'I have spent more time admiring this shot than any other one thus far.  Sheer determination is the only way to describe it.', '2006-01-22 07:20:01.000000', NULL, 1),
(2070117, 280456, 50715, '<td valign="top">Interesting idea, but way too much contrast, the blown-out highlights and lack of details in the shadows (particularly around you and your camera) don''t make it work very well.  Ditto the scenery which is not the most exciting or colourful - you could probably have picked a better location. The idea has merit, but the exectution doesn''t live up to it.</td>', 'Interesting idea, but way too much contrast, the blown-out highlights and lack of details in the shadows (particularly around you and your camera) don''t make it work very well.  Ditto the scenery which is not the most exciting or colourful - you could probably have picked a better location. The idea has merit, but the exectution doesn''t live up to it.', '2006-01-22 07:28:33.000000', NULL, 1),
(2070189, 281719, 29474, '<td valign="top">This is a beautiful portrait, but you have really stretched the challenge topic beyond breaking point.</td>', 'This is a beautiful portrait, but you have really stretched the challenge topic beyond breaking point.', '2006-01-22 08:33:11.000000', NULL, 1),
(2070191, 280727, 29474, '<td valign="top">The coulours seem to be a bland. I have a feeling that there is more to be got out of this picture.</td>', 'The coulours seem to be a bland. I have a feeling that there is more to be got out of this picture.', '2006-01-22 08:34:50.000000', NULL, 1),
(2070196, 282927, 2022, '<td valign="top">Beautiful (10)</td>', 'Beautiful (10)', '2006-01-22 08:37:52.000000', NULL, 1),
(2070201, 282992, 29474, '<td valign="top">The big white sky takes a lot away from an otherwise good picture.</td>', 'The big white sky takes a lot away from an otherwise good picture.', '2006-01-22 08:39:55.000000', NULL, 1),
(2070204, 281936, 29474, '<td valign="top">I think that the car lights actually spoil a lovely picture.</td>', 'I think that the car lights actually spoil a lovely picture.', '2006-01-22 08:42:43.000000', NULL, 1),
(2070237, 282449, 50036, '<td valign="top">It really looks like it''s leading to the moon! Very interesting!</td>', 'It really looks like it''s leading to the moon! Very interesting!', '2006-01-22 09:07:35.000000', NULL, 1),
(2070239, 282789, 50036, '<td valign="top">Unfortunately, it''s too small... But the lights and the colors are very nice.</td>', 'Unfortunately, it''s too small... But the lights and the colors are very nice.', '2006-01-22 09:11:17.000000', NULL, 1),
(2070240, 282984, 50036, '<td valign="top">Oh I really love this one... It reminds me of my own desicions I have to make...</td>', 'Oh I really love this one... It reminds me of my own desicions I have to make...', '2006-01-22 09:13:08.000000', NULL, 1),
(2070244, 280862, 51767, '<td valign="top">Nice photograph.  I think it needs more range to make the image have it''s real impact.</td>', 'Nice photograph.  I think it needs more range to make the image have it''s real impact.', '2006-01-22 09:17:25.000000', NULL, 1),
(2070285, 280102, 33392, '<td valign="top">I can''t believe the road is really purple.  This color balance feels very awkward.</td>', 'I can''t believe the road is really purple.  This color balance feels very awkward.', '2006-01-22 09:56:52.000000', NULL, 1),
(2070376, 279991, 40344, '<td valign="top">Very effective, the reflection of the driver in the mirror enhances this photo immensely.In my top ten.</td>', 'Very effective, the reflection of the driver in the mirror enhances this photo immensely.In my top ten.', '2006-01-22 10:34:32.000000', NULL, 1),
(2070411, 280292, 36914, '<td valign="top">Nice crisp, focus on the subject. camera did well on depth of field. The shutters on the barn could use some burning however, basic editting will not allow that.  Greens and browns make this pop,  Love the lighting and the balance of the overall shot.  Nature sure does take back what we leave behind.</td>', 'Nice crisp, focus on the subject. camera did well on depth of field. The shutters on the barn could use some burning however, basic editting will not allow that.  Greens and browns make this pop,  Love the lighting and the balance of the overall shot.  Nature sure does take back what we leave behind.', '2006-01-22 10:41:09.000000', NULL, 1),
(2070433, 280084, 51238, '<td valign="top">Interesting, but I think the shot would have been better if the focus was more towards the middle.</td>', 'Interesting, but I think the shot would have been better if the focus was more towards the middle.', '2006-01-22 10:46:55.000000', NULL, 1),
(2070437, 282252, 36914, '<td valign="top">The lean in this kind of distracts from this well focused nice compositioned photo.  Maybe step back back further from the gates and shoot from the right faceing down the road through the gates that could make a better view and allow the road to continue through. From this angle looks like the road ends at the gate and goes not further. Depth is good eveything fore and aft are well focused. Color is nice and crisp.</td>', 'The lean in this kind of distracts from this well focused nice compositioned photo.  Maybe step back back further from the gates and shoot from the right faceing down the road through the gates that could make a better view and allow the road to continue through. From this angle looks like the road ends at the gate and goes not further. Depth is good eveything fore and aft are well focused. Color is nice and crisp.', '2006-01-22 10:48:00.000000', NULL, 1),
(2070443, 282314, 51238, '<td valign="top">Fantastic, beautifull, yet somber.  I think this deserves the cake!</td>', 'Fantastic, beautifull, yet somber.  I think this deserves the cake!', '2006-01-22 10:49:32.000000', NULL, 1),
(2070452, 282451, 36914, '<td valign="top">Nicely balanced, clear and focused, darn that sun very hot. were you able to take more with the sun in a different part of the sky?</td>', 'Nicely balanced, clear and focused, darn that sun very hot. were you able to take more with the sun in a different part of the sky?', '2006-01-22 10:52:39.000000', NULL, 1),
(2070466, 279728, 36914, '<td valign="top">Slightly out of focus, the black and white adds to the misty feeling.  The girl against the tree draws away from the subject.  Perhaps just me, I would of sent her down the road to about the third tree on the right about center of the road, walking of into the mist.</td>', 'Slightly out of focus, the black and white adds to the misty feeling.  The girl against the tree draws away from the subject.  Perhaps just me, I would of sent her down the road to about the third tree on the right about center of the road, walking of into the mist.', '2006-01-22 10:57:27.000000', NULL, 1),
(2070474, 281594, 43156, '<td valign="top">I like this yellow S-curve, looks great.</td>', 'I like this yellow S-curve, looks great.', '2006-01-22 10:59:56.000000', NULL, 1),
(2070480, 280927, 50056, '<td valign="top">I really like this, but IMO I would have preferred a higher crop, and more negative space at top.  A nice job, and good luck!</td>', 'I really like this, but IMO I would have preferred a higher crop, and more negative space at top.  A nice job, and good luck!', '2006-01-22 11:03:19.000000', NULL, 1),
(2070486, 282694, 36914, '<td valign="top">Taking night shots like this is hard. Other that the Light flares this is a nicely shot. The tilt is very minimal from the left to the right. Depth and subject gives the felling of a city that has gone to sleep until the next day when this road is well traveled.</td>', 'Taking night shots like this is hard. Other that the Light flares this is a nicely shot. The tilt is very minimal from the left to the right. Depth and subject gives the felling of a city that has gone to sleep until the next day when this road is well traveled.', '2006-01-22 11:05:16.000000', NULL, 1),
(2070524, 282879, 36914, '<td valign="top">Thirds are layed out well.  The exposure was just a bit to long and darn that one distracting car. Sign and building are nicely focused.  Looks like your lense fogged up a little on the left above the car.</td>', 'Thirds are layed out well.  The exposure was just a bit to long and darn that one distracting car. Sign and building are nicely focused.  Looks like your lense fogged up a little on the left above the car.', '2006-01-22 11:16:46.000000', NULL, 1),
(2070540, 282782, 36914, '<td valign="top">Tilt is distracting. road is a little hot and and the glare of the front of the truck.  Does not seem that the road is the subject here but camel and the truck are.</td>', 'Tilt is distracting. road is a little hot and and the glare of the front of the truck.  Does not seem that the road is the subject here but camel and the truck are.', '2006-01-22 11:21:07.000000', NULL, 1),
(2070556, 281610, 36914, '<td valign="top">This may be better if the camera angle was more straight on to the subject<br/>maybe standing in the road was not an option.  Coming at the subject from the other side fo the road may have made a better composition. Lighting is very hot the current angle.  The depth of field is just not here.  Focus seems to be on the dashed lines on the top of the photo. To much fore ground and to little subject.</td>', 'This may be better if the camera angle was more straight on to the subjectmaybe standing in the road was not an option.  Coming at the subject from the other side fo the road may have made a better composition. Lighting is very hot the current angle.  The depth of field is just not here.  Focus seems to be on the dashed lines on the top of the photo. To much fore ground and to little subject.', '2006-01-22 11:26:08.000000', NULL, 1),
(2070612, 282555, 36914, '<td valign="top">Nice photo, good light well focused.  Layout from the Sky to the ground gives this a poster feel. If this was a one time shoot very nice.</td>', 'Nice photo, good light well focused.  Layout from the Sky to the ground gives this a poster feel. If this was a one time shoot very nice.', '2006-01-22 11:40:25.000000', NULL, 1),
(2070630, 282185, 36914, '<td valign="top">Here is one where the tilt actually works. Depth of field and layout well composed.  Nice shot of subject and very creative.</td>', 'Here is one where the tilt actually works. Depth of field and layout well composed.  Nice shot of subject and very creative.', '2006-01-22 11:46:38.000000', NULL, 1),
(2070638, 281808, 36914, '<td valign="top">Just the right amount of exposer not too much flare with the lights. The use of black and white add significantly to the quality of this photo.  Depth of field very well focused.</td>', 'Just the right amount of exposer not too much flare with the lights. The use of black and white add significantly to the quality of this photo.  Depth of field very well focused.', '2006-01-22 11:51:34.000000', NULL, 1),
(2070650, 282786, 24913, '<td valign="top">Should have been submitted to Signs.</td>', 'Should have been submitted to Signs.', '2006-01-22 11:56:30.000000', NULL, 1),
(2070653, 282872, 36914, '<td valign="top">Good stop action on the tire you can read the writing, more road would have made for a better composition. Nice crisp focus and use of black and white.</td>', 'Good stop action on the tire you can read the writing, more road would have made for a better composition. Nice crisp focus and use of black and white.', '2006-01-22 11:57:00.000000', NULL, 1),
(2070654, 282160, 50715, '<td valign="top">Too much contrast I think - too much detail lost in the shadows, and the sky is blown out to the point of featurelessness.  If it was a cloudless day, then blowing the sky out would at least not highlight that any more, but to lose so much shadow detail lets down the picture. Maybe if you''d gone into the curves and adjusted the greypoint to bring out some shadow detail, this could have been improved.</td>', 'Too much contrast I think - too much detail lost in the shadows, and the sky is blown out to the point of featurelessness.  If it was a cloudless day, then blowing the sky out would at least not highlight that any more, but to lose so much shadow detail lets down the picture. Maybe if you''d gone into the curves and adjusted the greypoint to bring out some shadow detail, this could have been improved.', '2006-01-22 11:57:02.000000', NULL, 1),
(2070679, 282777, 36914, '<td valign="top">Photo has good rule of thirds.  The title covers the long exposer, your camera handled it well.  No fogging (the yellowish haze that leeks in from the view finder or other lights that are not in your subject).</td>', 'Photo has good rule of thirds.  The title covers the long exposer, your camera handled it well.  No fogging (the yellowish haze that leeks in from the view finder or other lights that are not in your subject).', '2006-01-22 12:07:22.000000', NULL, 1),
(2070696, 281312, 36914, '<td valign="top">The way the lighting breaks up the photo from top to bottom divides this up nicely for a great composition. Yet the subject is still in clear view. Photo is nicely focused.  Is this a morning sun or a setting sun?</td>', 'The way the lighting breaks up the photo from top to bottom divides this up nicely for a great composition. Yet the subject is still in clear view. Photo is nicely focused.  Is this a morning sun or a setting sun?', '2006-01-22 12:13:06.000000', NULL, 1),
(2070715, 280482, 36914, '<td valign="top">If this photo could have been composed.  A a better angle of shooting from the left side and focusing on the man pulling the cart facing with a little more road behind him.  Looks like the focus grabed the cart and left the subject slighty out of focus.</td>', 'If this photo could have been composed.  A a better angle of shooting from the left side and focusing on the man pulling the cart facing with a little more road behind him.  Looks like the focus grabed the cart and left the subject slighty out of focus.', '2006-01-22 12:19:45.000000', NULL, 1),
(2070723, 283005, 36914, '<td valign="top">Brrr, the color of the truck and the subject work well.  White, brown gray and Pop red. Gives the the feeling of a cold and lonely trip up a snow covered road.  Almost seems like this is a black and white photo with the road and car colored. Nice depth of field and well focused.</td>', 'Brrr, the color of the truck and the subject work well.  White, brown gray and Pop red. Gives the the feeling of a cold and lonely trip up a snow covered road.  Almost seems like this is a black and white photo with the road and car colored. Nice depth of field and well focused.', '2006-01-22 12:23:28.000000', NULL, 1),
(2070743, 280691, 36914, '<td valign="top">Very well exposed no star burst with the yard lights and the car light streams are well focused, the fore and back ground are very crisp and not to hot. Subject is well placed in the photo it gives the feeling of a cold winter drive on a snowy highway into the mountains beyond.</td>', 'Very well exposed no star burst with the yard lights and the car light streams are well focused, the fore and back ground are very crisp and not to hot. Subject is well placed in the photo it gives the feeling of a cold winter drive on a snowy highway into the mountains beyond.', '2006-01-22 12:30:02.000000', NULL, 1),
(2070778, 281502, 30982, '<td valign="top">Very nice detail.</td>', 'Very nice detail.', '2006-01-22 12:37:39.000000', NULL, 1),
(2070788, 280102, 30982, '<td valign="top">Good perspective - odd color, but I like it.</td>', 'Good perspective - odd color, but I like it.', '2006-01-22 12:40:21.000000', NULL, 1),
(2070789, 279852, 36914, '<td valign="top">Finding the correct timing and getting rid of that star effect is very hard.<br/>the fore light and the on coming car lights are very distracting.  Not much digital noise for a night shot, camera handled that well.  Subject is focused well.  Kind of neat that you captured this from the front seat of your car and the light pole behind you came out well in the mirror.</td>', 'Finding the correct timing and getting rid of that star effect is very hard.the fore light and the on coming car lights are very distracting.  Not much digital noise for a night shot, camera handled that well.  Subject is focused well.  Kind of neat that you captured this from the front seat of your car and the light pole behind you came out well in the mirror.', '2006-01-22 12:40:44.000000', NULL, 1),
(2070793, 281719, 36914, '<td valign="top">Good cover, the title shows imagination.  Nice use of black and white, subject is well focused.</td>', 'Good cover, the title shows imagination.  Nice use of black and white, subject is well focused.', '2006-01-22 12:44:14.000000', NULL, 1),
(2070795, 282967, 30982, '<td valign="top">Great clarity for a reflection!</td>', 'Great clarity for a reflection!', '2006-01-22 12:44:38.000000', NULL, 1),
(2070801, 282861, 30982, '<td valign="top">I like the idea, but it''s just a little too blurry I think.</td>', 'I like the idea, but it''s just a little too blurry I think.', '2006-01-22 12:46:02.000000', NULL, 1),
(2070809, 280927, 30982, '<td valign="top">Great composition!</td>', 'Great composition!', '2006-01-22 12:47:12.000000', NULL, 1),
(2070811, 282928, 36914, '<td valign="top">Focus seems off, mabe show a little more of the running track.  The blurd feet does show movement,</td>', 'Focus seems off, mabe show a little more of the running track.  The blurd feet does show movement,', '2006-01-22 12:47:56.000000', NULL, 1),
(2070820, 282449, 30982, '<td valign="top">Great capture!</td>', 'Great capture!', '2006-01-22 12:50:39.000000', NULL, 1),
(2070822, 280932, 36914, '<td valign="top">Seems slighly out of focus, maybe cause by some camera movement.  The shadow down the center of the road distracts a little.  The color seems a little off too much yellow orange.</td>', 'Seems slighly out of focus, maybe cause by some camera movement.  The shadow down the center of the road distracts a little.  The color seems a little off too much yellow orange.', '2006-01-22 12:52:02.000000', NULL, 1),
(2070831, 280397, 30982, '<td valign="top">Very good perspective - love the way the road reflects in the building - perfect!</td>', 'Very good perspective - love the way the road reflects in the building - perfect!', '2006-01-22 12:55:38.000000', NULL, 1),
(2070843, 282020, 36914, '<td valign="top">Nicely layed out. Thirds are here. Both the road and the person walking it are well in focus and the back ground is nicly blurd not to distract from the subject.  The women in the picture does not look posed even though she knows the picture is being taken.</td>', 'Nicely layed out. Thirds are here. Both the road and the person walking it are well in focus and the back ground is nicly blurd not to distract from the subject.  The women in the picture does not look posed even though she knows the picture is being taken.', '2006-01-22 12:58:11.000000', NULL, 1),
(2070855, 283013, 30982, '<td valign="top">I like the motion of the flags.</td>', 'I like the motion of the flags.', '2006-01-22 13:01:20.000000', NULL, 1),
(2070866, 282932, 36914, '<td valign="top">Now this does show a new perspective.  Nice use of challenge and a good risk to take.  This definably messes with the mind.</td>', 'Now this does show a new perspective.  Nice use of challenge and a good risk to take.  This definably messes with the mind.', '2006-01-22 13:04:07.000000', NULL, 1),
(2070875, 282991, 36914, '<td valign="top">Having the palms in the pictures adds the balance with out distracting from the subject. Nicly composed and well exposed not harsh just right.</td>', 'Having the palms in the pictures adds the balance with out distracting from the subject. Nicly composed and well exposed not harsh just right.', '2006-01-22 13:07:55.000000', NULL, 1),
(2070890, 281445, 36914, '<td valign="top">Brightness could be toned down alot.  Seems a tad out of focus.</td>', 'Brightness could be toned down alot.  Seems a tad out of focus.', '2006-01-22 13:12:26.000000', NULL, 1),
