(2073870, 281364, 48228, '<td valign="top">I love the title, and I also like this image for it simplicity.....</td>', 'I love the title, and I also like this image for it simplicity.....', '2006-01-23 09:50:51.000000', NULL, 1),
(2073873, 282635, 48228, '<td valign="top">Bright city lights, illuminate this very well.....</td>', 'Bright city lights, illuminate this very well.....', '2006-01-23 09:51:49.000000', NULL, 1),
