(2073892, 282587, 48228, '<td valign="top">Cars a plenty here, red, striped, bold, powerful machines.....</td>', 'Cars a plenty here, red, striped, bold, powerful machines.....', '2006-01-23 10:00:08.000000', NULL, 1),
(2073893, 280241, 48228, '<td valign="top">Very sharp focusing, in the flower and the stones on the road.....</td>', 'Very sharp focusing, in the flower and the stones on the road.....', '2006-01-23 10:01:51.000000', NULL, 1),
(2073896, 282835, 48228, '<td valign="top">Pleasing image...</td>', 'Pleasing image...', '2006-01-23 10:02:43.000000', NULL, 1),
