INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2080713, 282694, 48546, '<td valign="top">woohoo. Hennepin Ave. Bridge. Go Twin Cities.<br/>Congrats on your 5th place.</td>', 'woohoo. Hennepin Ave. Bridge. Go Twin Cities.Congrats on your 5th place.', '2006-01-25 01:49:13.000000', NULL, 0),
(2080716, 282449, 38464, '<td valign="top">Am sorry about that Robert. :(  Great image!!<br/> <br/>And that you took it on Cardsound... OMG, you should get extra points just for the bravery of that! When I lived down there, we used to go fishing under the bridge all the time. And travel to/from the keys doesn''t stop just cuz it''s night time. If anything, they drive faster! ;) Nice to see someone on here from my hometown!! :D</td>', 'Am sorry about that Robert. :(  Great image!! And that you took it on Cardsound... OMG, you should get extra points just for the bravery of that! When I lived down there, we used to go fishing under the bridge all the time. And travel to/from the keys doesn''t stop just cuz it''s night time. If anything, they drive faster! ;) Nice to see someone on here from my hometown!! :D', '2006-01-25 01:49:25.000000', NULL, 0),
(2080721, 279905, 37893, '<td valign="top">For some reason, I knew this was you Caleb. Maybe it''s the beanie :) Great job and congrats on top 20.</td>', 'For some reason, I knew this was you Caleb. Maybe it''s the beanie :) Great job and congrats on top 20.', '2006-01-25 01:49:51.000000', NULL, 0),
(2080740, 282159, 42506, '<td valign="top">Thank you all who voted. Now I''m officially hooked</td>', 'Thank you all who voted. Now I''m officially hooked', '2006-01-25 01:52:56.000000', NULL, 0),
